const readSaved=(key,fallback)=>{try{const v=localStorage.getItem(key);return v?JSON.parse(v):fallback}catch{return fallback}};
const framesFrom=(items,steps)=>steps.map(s=>({label:s.label,detail:s.detail,items:s.items??items,active:s.active??-1,aux:s.aux??""}));
const parseNums=(s)=>s.split(",").map(x=>Number(x.trim())).filter(x=>Number.isFinite(x));
const precedence={"+":1,"-":1,"*":2,"/":2,"%":2,"^":3};

function tokenize(expr){return expr.match(/\d+(?:\.\d+)?|[A-Za-z_]\w*|[()+\-*/%^]/g)||[]}
function infixConvert(expr){
 const compact=expr.replace(/\s+/g,""); const tokens=tokenize(compact); if(!tokens.length) throw Error("Enter an expression first, for example A+B*C."); if(tokens.join("")!==compact) throw Error("The expression contains an unsupported character. Use letters, numbers, parentheses, and + - * / % ^.");
 const out=[],ops=[],steps=[];
 for(const t of tokens){
  if(/^[\w]+$/.test(t)||/^\d/.test(t)){out.push(t);steps.push({label:`Send ${t} to output`,detail:`${t} is an operand, so it goes directly to the postfix output.`,items:[...out],aux:`Operator stack: ${ops.join(" ")||"empty"}`});}
  else if(t==="("){ops.push(t);steps.push({label:"Push opening bracket",detail:"An opening bracket marks a separate expression. Operators inside it stay on the stack until the matching closing bracket.",items:[...out],aux:`Operator stack: ${ops.join(" ")}`});}
  else if(t===")"){if(!ops.includes("("))throw Error("The parentheses do not match.");while(ops.length&&ops.at(-1)!=="("){const op=ops.pop();out.push(op);steps.push({label:`Pop ${op} to output`,detail:`The closing bracket means we finish the bracketed part, so ${op} moves to the output.`,items:[...out],aux:`Operator stack: ${ops.join(" ")||"empty"}`});}ops.pop();}
  else if(precedence[t]){while(ops.length&&ops.at(-1)!=="("&&(precedence[ops.at(-1)]>precedence[t]||(precedence[ops.at(-1)]===precedence[t]&&t!=="^"))){const op=ops.pop();out.push(op);steps.push({label:`Pop ${op} by precedence`,detail:`${op} has higher or equal precedence, so it must appear before ${t}.`,items:[...out],aux:`Operator stack: ${ops.join(" ")||"empty"}`});}ops.push(t);steps.push({label:`Push operator ${t}`,detail:`Keep ${t} on the operator stack until its correct output position is known.`,items:[...out],aux:`Operator stack: ${ops.join(" ")}`});}
  else throw Error(`Unknown token: ${t}`);
 }
 if(tokens.filter(t=>t==="(").length!==tokens.filter(t=>t===")").length)throw Error("The parentheses do not match.");
 while(ops.length){const op=ops.pop();if(op==="(")throw Error("The parentheses do not match.");out.push(op);steps.push({label:`Flush ${op}`,detail:`The expression is finished, so the remaining operator ${op} moves to output.`,items:[...out],aux:`Operator stack: ${ops.join(" ")||"empty"}`});}
 steps.push({label:"Conversion complete",detail:`The postfix expression is ${out.join(" ")}.`,items:out,aux:"Every operator now appears after its operands."});
 return {out,steps};
}
function evaluatePostfix(expr){
 const ts=expr.trim().split(/\s+/).filter(Boolean);if(!ts.length)throw Error("Enter a space-separated postfix expression, such as 5 2 3 * +.");
 const st=[],steps=[];
 for(const t of ts){
  if(!Number.isNaN(Number(t))){st.push(Number(t));steps.push({label:`Push ${t}`,detail:`${t} is a number, so place it on the stack.`,items:[...st]});}
  else if(["+","-","*","/","%","^"].includes(t)){if(st.length<2)throw Error(`Not enough operands for ${t}. Check your postfix expression.`);const right=st.pop(),left=st.pop();if((t==="/"||t==="%")&&right===0)throw Error("Division by zero is not allowed.");const result=t==="+"?left+right:t==="-"?left-right:t==="*"?left*right:t==="/"?left/right:t==="%"?left%right:left**right;st.push(Number(result.toFixed(6)));steps.push({label:`Calculate ${left} ${t} ${right}`,detail:`Pop right operand ${right}, then left operand ${left}. Calculate the result and push ${Number(result.toFixed(6))}.`,items:[...st]});}
  else throw Error(`Unknown token "${t}". Use numbers and operators separated by spaces.`);
 }
 if(st.length!==1)throw Error("This expression is incomplete or has extra operands. A valid postfix expression leaves exactly one value.");
 steps.push({label:"Final answer",detail:`The only value left on the stack is ${st[0]}.`,items:[...st]});return {result:st[0],steps};
}
function traversal(kind){
 const graph={A:["B","C"],B:["A","D","E"],C:["A","F"],D:["B"],E:["B","F"],F:["C","E"]},order=[],steps=[],seen=new Set();
 if(kind==="BFS"){const q=["A"];seen.add("A");steps.push({label:"Start at A",detail:"Put starting vertex A in the queue and mark it visited.",items:[...order],aux:`Queue: ${q.join(", ")}`});while(q.length){const v=q.shift();order.push(v);steps.push({label:`Visit ${v}`,detail:`Remove ${v} from the front of the queue. Check its neighbours in order.`,items:[...order],active:order.length-1,aux:`Queue: ${q.join(", ")||"empty"}`});for(const n of graph[v])if(!seen.has(n)){seen.add(n);q.push(n);steps.push({label:`Add neighbour ${n}`,detail:`${n} has not been visited, so mark it and add it to the queue.`,items:[...order],aux:`Queue: ${q.join(", ")}`});}}}
 else {const st=["A"];seen.add("A");while(st.length){const v=st.pop();order.push(v);steps.push({label:`Visit ${v}`,detail:`Pop ${v} from the stack. DFS explores one path deeply before backtracking.`,items:[...order],active:order.length-1,aux:`Stack: ${st.join(", ")||"empty"}`});[...graph[v]].reverse().forEach(n=>{if(!seen.has(n)){seen.add(n);st.push(n);}});if(st.length)steps.push({label:"Choose next path",detail:`Add unvisited neighbours to the stack. The last added neighbour is explored next.`,items:[...order],aux:`Stack: ${st.join(", ")}`});}}
 steps.push({label:"Traversal complete",detail:`${kind} visited the vertices in this order: ${order.join(" → ")}.`,items:order,aux:"All reachable vertices have been visited."});return {order,steps};
}
function hanoi(n){
 const rods={A:Array.from({length:n},(_,i)=>n-i),B:[],C:[]},moves=[],steps=[];
 function move(k,from,to,aux){if(!k)return;move(k-1,from,aux,to);const disk=rods[from].pop();rods[to].push(disk);moves.push(`Move disk ${disk} from ${from} to ${to}`);steps.push({label:`Move disk ${disk}`,detail:`Move disk ${disk} from rod ${from} to rod ${to}. The move is legal because a larger disk is never placed on a smaller disk.`,items:[`A: ${rods.A.join(",")||"empty"}`,`B: ${rods.B.join(",")||"empty"}`,`C: ${rods.C.join(",")||"empty"}`],aux:`A: ${rods.A.join(",")||"empty"} | B: ${rods.B.join(",")||"empty"} | C: ${rods.C.join(",")||"empty"}`});move(k-1,aux,to,from);}
 move(n,"A","C","B");return steps;
}

// Beginner code examples live in src/code/<topic>/ as real files (main.c, main.cpp, main.py, Main.java).
// Vite loads them as plain text with ?raw, so you can edit them like normal code files.
const codeFiles = import.meta.glob("./code/*/*", { query: "?raw", import: "default", eager: true });
const codeFileName = { "C": "main.c", "C++": "main.cpp", "Python": "main.py", "Java": "Main.java" };

// Which example folder each topic uses, plus a short beginner note.
const codeTopics = {
  "Stack": ["stack", "Push adds on top, Pop removes from the top. The variable top remembers where the top is."],
  "Queue": ["queue", "Enqueue adds at the rear, Dequeue removes from the front."],
  "Linked List": ["linked-list", "Each node holds data and a link (next) to the following node."],
  "Binary Tree": ["bst", "A simple tree with left and right children. Here it is a Binary Search Tree, the most common kind."],
  "Binary Search Tree": ["bst", "Smaller values go left, larger values go right. Inorder printing gives sorted output."],
  "AVL Tree": ["bst", "An AVL tree is a BST that also rebalances itself. This is the plain BST it builds on; rotations come after you understand this."],
  "Expression Tree": ["bst", "An expression tree is built like other trees (a node with left and right children). This shows the basic tree code."],
  "B-tree": ["bst", "A B-tree is a multi-key version of a search tree. Understand this BST first, then the idea of several keys per node is easier."],
  "Infix to Postfix": ["infix-postfix", "A stack holds operators until it is their turn. * and / are done before + and -."],
  "Postfix Expression Evaluation": ["postfix-eval", "Push numbers. When you see an operator, pop two numbers, calculate, push the answer."],
  "Tower of Hanoi": ["hanoi", "A classic recursion: move n-1 disks away, move the big disk, move n-1 disks back on top."],
  "Graph Traversals": ["graph", "BFS visits neighbours first using a queue. DFS goes deep first using recursion."],
  "Hashing – Separate Chaining": ["chaining", "Every table slot holds a list, so keys that collide simply share the list."],
  "Hashing – Open Addressing": ["linear-probing", "If a slot is taken, look for another empty slot. Linear probing is the simplest way to do that."],
  "Hashing – Linear Probing": ["linear-probing", "If a slot is taken, try the next one (index+1, index+2, ...), wrapping around."],
  "Hashing – Quadratic Probing": ["linear-probing", "Same idea as linear probing. To make it quadratic, change (index + i) to (index + i * i)."],
  "Hashing – Double Hashing": ["linear-probing", "Same idea as linear probing. For double hashing, use a second hash for the step: (index + i * step)."],
  "Rehashing": ["linear-probing", "Rehashing = make a bigger table and insert every key again with the new SIZE. Try changing SIZE and re-inserting."],
  "Linear Search": ["linear-search", "Check each value from the start until you find the target."],
  "Binary Search": ["binary-search", "Works only on sorted data. Check the middle, then throw away half of the list."],
  "Internal Sorting": ["bubble-sort", "Internal sorting means all data fits in memory. Bubble sort is the easiest example."],
  "Bubble Sort": ["bubble-sort", "Compare neighbours and swap them if they are in the wrong order."],
  "Shell Sort": ["shell-sort", "Like insertion sort, but it first compares values that are far apart (the gap)."],
  "External Sorting": ["merge", "External sorting sorts small chunks, then merges them. This is the merge step."],
  "Multiway Merge": ["merge", "Shown with two runs to keep it simple. Multiway merge repeats the same idea with more runs."],
  "Polyphase Merge": ["merge", "Polyphase merge is built from repeated merges like this one."]
};

function getCodeExample(topic, language) {
  const entry = codeTopics[topic] || codeTopics["Stack"];
  const code = codeFiles[`./code/${entry[0]}/${codeFileName[language]}`] || "// Example not found";
  return { code, note: entry[1], file: codeFileName[language] };
}

export default function App(){
 const [page,setPage]=useState("Home"),[activeConcept,setActiveConcept]=useState("Stack");
 const [input,setInput]=useState(""),[arrayInput,setArrayInput]=useState(""),[target,setTarget]=useState(""),[operation,setOperation]=useState("Push");
 const [frames,setFrames]=useState([]),[frameIndex,setFrameIndex]=useState(0),[notice,setNotice]=useState("Your simulator is empty. Enter a value and choose an operation to begin.");
 const [voiceOn,setVoiceOn]=useState(false),[voiceRate,setVoiceRate]=useState(0.92);
 const [items,setItems]=useState([]),[graphData,setGraphData]=useState({vertices:[],edges:[]}),[completed,setCompleted]=useState(readSaved("dsplay-completed",[]));
 const [profileName,setProfileName]=useState(readSaved("dsplay-name","Student")),[sidebarOpen,setSidebarOpen]=useState(false);
 const [chatInput,setChatInput]=useState(""),[messages,setMessages]=useState([{from:"bot",text:"Hello! Choose a topic or ask me a question. I can explain it in beginner-friendly steps."}]);
 const [answers,setAnswers]=useState({}),[submitted,setSubmitted]=useState(false);
 const [practiceFilter,setPracticeFilter]=useState("All");
 const [codeLanguage,setCodeLanguage]=useState("C"),[copied,setCopied]=useState(false);
 const concept=concepts.find(c=>c.id===activeConcept)||concepts[0];
 const current=frames[frameIndex];
 useEffect(()=>{localStorage.setItem("dsplay-completed",JSON.stringify(completed));},[completed]);
 useEffect(()=>{localStorage.setItem("dsplay-name",JSON.stringify(profileName));},[profileName]);
 useEffect(()=>{
  if(!voiceOn||!current||!("speechSynthesis" in window)) return;
  window.speechSynthesis.cancel();
  const utterance=new SpeechSynthesisUtterance(`${current.label}. ${current.detail}`);
  utterance.rate=voiceRate;
  // Keep the visual frame and narration in sync: after one explanation finishes,
  // automatically advance to the next frame and speak it until the process ends.
  utterance.onend=()=>{
   setFrameIndex(index=>{
    if(index<frames.length-1) return index+1;
    setNotice("Process complete. You can replay any step or try another operation.");
    return index;
   });
  };
  window.speechSynthesis.speak(utterance);
  return()=>{utterance.onend=null;window.speechSynthesis.cancel();};
 },[voiceOn,current,frameIndex,voiceRate,frames.length]);
 useEffect(()=>()=>{if("speechSynthesis"in window)window.speechSynthesis.cancel();},[]);
 function chooseConcept(id){setActiveConcept(id);setPage("Simulator");setInput("");setArrayInput("");setTarget("");setItems([]);if(id==="Graph Traversals")setGraphData({vertices:[],edges:[]});setFrames([]);setFrameIndex(0);setOperation("Push");setNotice(`Welcome to ${id}. Read the beginner explanation, then enter your first value.`);setSidebarOpen(false);}
 function showSteps(steps,message,finalItems){if(!steps?.length){setNotice("No steps were generated. Check your input and try again.");return;}setFrames(steps);setFrameIndex(0);setNotice(message);if(finalItems)setItems(finalItems);setCompleted(old=>old.includes(activeConcept)?old:[...old,activeConcept]);}
 function execute(actionOverride){
  const op=actionOverride||operation;
  try{
   const c=activeConcept,v=input.trim();let steps=[],result=[];
   if(c==="Stack"){if(op==="Push"){if(!v)throw Error("Enter a value before pressing Push.");if(items.length>=8)throw Error("Stack is full in this demo. Reset it before adding more values.");result=[...items,v];steps=[{label:"Check capacity",detail:"First check that the stack has an empty position.",items:[...items]},{label:"Move TOP upward",detail:"TOP moves to the next free position.",items:[...items]},{label:`Push ${v}`,detail:`Store ${v} at the top. It is now the newest item.`,items:result,active:result.length-1}];}else if(op==="Pop"){if(!items.length)throw Error("Stack underflow: there is no item to remove.");const x=items.at(-1);result=items.slice(0,-1);steps=[{label:"Read TOP",detail:`The top item is ${x}.`,items:[...items],active:items.length-1},{label:"Remove TOP",detail:`Remove ${x}. The item below it becomes the new top.`,items:result,active:result.length-1}];}else{if(!items.length)throw Error("The stack is empty. Push a value first.");steps=[{label:"Peek at TOP",detail:`The top value is ${items.at(-1)}. Peek only looks; it does not remove the value.`,items:[...items],active:items.length-1}];result=items;}}
   else if(c==="Queue"){if(op==="Enqueue"){if(!v)throw Error("Enter a value before enqueueing.");result=[...items,v];steps=[{label:"Find REAR",detail:"Find the rear end of the queue.",items:[...items]},{label:`Enqueue ${v}`,detail:`Add ${v} at the rear. Existing values stay in their order.`,items:result,active:result.length-1}];}else if(op==="Dequeue"){if(!items.length)throw Error("Queue is empty. Enqueue a value first.");const x=items[0];result=items.slice(1);steps=[{label:"Read FRONT",detail:`The front item is ${x}.`,items:[...items],active:0},{label:"Dequeue",detail:`Remove ${x} from the front. The next item becomes the front.`,items:result,active:0}];}else{if(!items.length)throw Error("Queue is empty.");result=items;steps=[{label:"Peek at FRONT",detail:`The next item to leave is ${items[0]}. Nothing is removed.`,items:[...items],active:0}];}}
   else if(c==="Linked List"){if(op==="Insert"){if(!v)throw Error("Enter a value to insert.");result=[v,...items];steps=[{label:"Create a node",detail:`Create a new node containing ${v}.`,items:[...items]},{label:"Connect the node",detail:"Set the new node's next link to the old head.",items:result,active:0},{label:"Update HEAD",detail:`HEAD now points to ${v}.`,items:result,active:0}];}else if(op==="Delete"){if(!items.length)throw Error("The linked list is empty.");result=items.slice(1);steps=[{label:"Read HEAD",detail:`The first node contains ${items[0]}.`,items:[...items],active:0},{label:"Move HEAD",detail:"HEAD now points to the second node. The old first node is removed.",items:result,active:0}];}else{if(!v)throw Error("Enter the value you want to find.");const ix=items.indexOf(v);steps=items.map((x,i)=>({label:`Check node ${i+1}`,detail:`Compare ${x} with ${v}. ${x===v?"The values match.":"They do not match, so follow the next link."}`,items:[...items],active:i}));if(!steps.length)steps=[{label:"Empty list",detail:"There are no nodes to search.",items:[]}];if(ix<0)steps.push({label:"Not found",detail:`${v} is not present in this linked list.`,items:[...items]});result=items;}}
   else if(c==="Infix to Postfix"){const r=infixConvert(v);steps=r.steps.map(s=>({...s,items:s.items}));result=r.out;}
   else if(c==="Postfix Expression Evaluation"){const r=evaluatePostfix(v);steps=r.steps;result=[String(r.result)];}
   else if(c==="Graph Traversals"){
    const label=v.trim().toUpperCase();let vertices=[...graphData.vertices],edges=[...graphData.edges];
    const edgeParts=label.split(/[,-]/).map(x=>x.trim()).filter(Boolean);
    if(op==="Add Vertex") {if(!/^[A-Z0-9]$/.test(label))throw Error("Enter one vertex label, such as A or 1.");if(vertices.includes(label))throw Error(`Vertex ${label} already exists.`);vertices.push(label);steps=[{label:`Create vertex ${label}`,detail:`Add ${label} as a new point in the graph. It has no connections yet.`,items:vertices}];setGraphData({vertices,edges});result=vertices;}
    else if(op==="Add Edge") {if(edgeParts.length!==2)throw Error("Enter an edge like A-B. Add both vertices first.");const [a,b]=edgeParts;if(!vertices.includes(a)||!vertices.includes(b))throw Error("Both endpoint vertices must exist before adding an edge.");if(a===b)throw Error("A vertex cannot connect to itself in this simple demo.");if(edges.some(e=>(e[0]===a&&e[1]===b)||(e[0]===b&&e[1]===a)))throw Error("That edge already exists.");edges.push([a,b]);steps=[{label:`Connect ${a} and ${b}`,detail:`Create an undirected edge between ${a} and ${b}. Both vertices are now neighbours.`,items:vertices,aux:`Edges: ${edges.map(e=>e.join("—")).join(", ")}`}];setGraphData({vertices,edges});result=vertices;}
    else if(op==="Delete Vertex") {if(!vertices.includes(label))throw Error(`Vertex ${label} does not exist.`);vertices=vertices.filter(x=>x!==label);edges=edges.filter(e=>!e.includes(label));steps=[{label:`Remove vertex ${label}`,detail:`Delete ${label} and also remove every edge connected to it.`,items:vertices,aux:`Remaining edges: ${edges.map(e=>e.join("—")).join(", ")||"none"}`}];setGraphData({vertices,edges});result=vertices;}
    else if(op==="Delete Edge") {if(edgeParts.length!==2)throw Error("Enter the edge to remove, like A-B.");const [a,b]=edgeParts;const before=edges.length;edges=edges.filter(e=>!((e[0]===a&&e[1]===b)||(e[0]===b&&e[1]===a)));if(edges.length===before)throw Error(`Edge ${a}-${b} was not found.`);steps=[{label:`Remove edge ${a}-${b}`,detail:`Delete the connection between ${a} and ${b}. The vertices remain in the graph.`,items:vertices}];setGraphData({vertices,edges});result=vertices;}
    else if(op==="Search") {if(!vertices.includes(label))throw Error(`Vertex ${label} was not found.`);steps=[{label:`Find vertex ${label}`,detail:`The graph contains vertex ${label}. Its neighbours are ${edges.filter(e=>e.includes(label)).map(e=>e[0]===label?e[1]:e[0]).join(", ")||"none yet"}.`,items:vertices,active:vertices.indexOf(label)}];result=vertices;}
    else if(op==="BFS"||op==="DFS") {if(!vertices.length)throw Error("Add vertices and edges before running a traversal.");const start=label||vertices[0];if(!vertices.includes(start))throw Error(`Starting vertex ${start} does not exist.`);const adj=Object.fromEntries(vertices.map(x=>[x,[]]));edges.forEach(([a,b])=>{adj[a].push(b);adj[b].push(a);});const seen=new Set([start]),order=[];if(op==="BFS"){const q=[start];steps.push({label:`Start at ${start}`,detail:`Put ${start} into the queue. The queue decides which vertex is visited next.`,items:[],aux:`Queue: ${q.join(", ")}`});while(q.length){const node=q.shift();order.push(node);steps.push({label:`Visit ${node}`,detail:`Remove ${node} from the front of the queue and visit it.`,items:[...order],active:order.length-1,aux:`Queue: ${q.join(", ")||"empty"}`});adj[node].forEach(next=>{if(!seen.has(next)){seen.add(next);q.push(next);steps.push({label:`Queue neighbour ${next}`,detail:`${next} is connected and not visited yet, so add it to the back of the queue.`,items:[...order],aux:`Queue: ${q.join(", ")}`});}});}}else{const stack=[start];while(stack.length){const node=stack.pop();if(seen.has(node)&&order.includes(node))continue;seen.add(node);order.push(node);steps.push({label:`Visit ${node}`,detail:`Take ${node} from the top of the stack. DFS follows one branch as deeply as possible.`,items:[...order],active:order.length-1,aux:`Stack: ${stack.join(", ")||"empty"}`});[...adj[node]].reverse().forEach(next=>{if(!seen.has(next))stack.push(next);});}}steps.push({label:`${op} complete`,detail:`Starting at ${start}, the traversal visited: ${order.join(" → ")}.`,items:order});result=order;}
   }
   else if(c==="Tower of Hanoi"){const n=Number(v);if(!Number.isInteger(n)||n<1||n>5)throw Error("Enter a whole number of disks from 1 to 5.");steps=hanoi(n);result=[`Solved in ${steps.length} moves`];}
   else if(["Linear Search","Binary Search"].includes(c)){const arr=parseNums(arrayInput);if(!arr.length)throw Error("Enter comma-separated numbers in the values field.");if(target.trim()===""||!Number.isFinite(Number(target)))throw Error("Enter a numeric target.");if(c==="Binary Search"&&arr.some((x,i)=>i&&arr[i-1]>x))throw Error("Binary search needs ascending sorted values. Sort your input first.");let lo=0,hi=arr.length-1,found=-1;if(c==="Linear Search"){for(let i=0;i<arr.length;i++){const yes=arr[i]===Number(target);steps.push({label:`Compare index ${i}`,detail:`Check ${arr[i]} against ${target}. ${yes?"Target found!":"Not a match, move to the next value."}`,items:arr,active:i});if(yes){found=i;break;}}}else{while(lo<=hi){const mid=Math.floor((lo+hi)/2),x=arr[mid],yes=x===Number(target);steps.push({label:`Check middle index ${mid}`,detail:`Low=${lo}, high=${hi}, middle=${mid}. Compare ${x} with ${target}.`,items:arr,active:mid,aux:`Search range: ${lo} to ${hi}`});if(yes){found=mid;break;}if(x<Number(target))lo=mid+1;else hi=mid-1;}}if(found<0)steps.push({label:"Target not found",detail:`${target} is not present in the search range.`,items:arr});else steps.push({label:"Target found",detail:`Found ${target} at index ${found} (position ${found+1}).`,items:arr,active:found});result=arr;}
   else if(["Bubble Sort","Internal Sorting"].includes(c)){const arr=parseNums(arrayInput);if(!arr.length)throw Error("Enter comma-separated numbers to sort.");result=[...arr];for(let end=arr.length-1;end>0;end--){let swapped=false;for(let j=0;j<end;j++){const before=[...result];if(result[j]>result[j+1]){[result[j],result[j+1]]=[result[j+1],result[j]];swapped=true;}steps.push({label:`Compare ${before[j]} and ${before[j+1]}`,detail:before[j]>before[j+1]?`They are out of order, so swap them. The array becomes ${result.join(", ")}.`:`They are already in order, so no swap is needed.`,items:[...result],active:j});}steps.push({label:"Pass complete",detail:`The largest unsorted value is now in its final position.`,items:[...result]});if(!swapped)break;}steps.push({label:"Sorting complete",detail:`Sorted result: ${result.join(", ")}.`,items:result});}
   else if(c==="Shell Sort"){const arr=parseNums(arrayInput);if(!arr.length)throw Error("Enter comma-separated numbers to sort.");result=[...arr];for(let gap=Math.floor(result.length/2);gap>0;gap=Math.floor(gap/2)){for(let i=gap;i<result.length;i++){let temp=result[i],j=i;while(j>=gap&&result[j-gap]>temp){result[j]=result[j-gap];j-=gap;steps.push({label:`Shift using gap ${gap}`,detail:`Move ${result[j]} forward to make room for ${temp}.`,items:[...result],active:j});}result[j]=temp;steps.push({label:`Insert ${temp} at gap ${gap}`,detail:`Place ${temp} in its correct position for this gap.`,items:[...result],active:j});}}steps.push({label:"Shell sort complete",detail:`Sorted result: ${result.join(", ")}.`,items:result});}
   else if(c.startsWith("Hashing")){const keys=parseNums(v);if(!keys.length)throw Error("Enter numeric keys separated by commas, for example 10,17,24.");const table=Array.from({length:7},()=>[]);const strategy=c.includes("Separate")?"chain":c.includes("Quadratic")?"quadratic":c.includes("Double")?"double":c.includes("Linear")?"linear":"linear";for(const key of keys){const home=((key%7)+7)%7;let index=home,probe=0;while(probe<7&&table[index].length){steps.push({label:`Collision at ${index}`,detail:`Key ${key} hashes to ${home}, but index ${index} is occupied. Try another location.`,items:table.map((b,i)=>`${i}: ${b.join(" → ")||"—"}`),active:index});if(strategy==="chain")break;probe++;index=strategy==="quadratic"?(home+probe*probe)%7:strategy==="double"?(home+probe*(1+(key%5)))%7:(home+probe)%7;}if(strategy==="chain")table[home].push(key);else if(probe>=7)throw Error("The table is full. Try rehashing.");else table[index].push(key);steps.push({label:`Insert ${key}`,detail:strategy==="chain"?`Add ${key} to the chain at bucket ${home}.`:`Place ${key} at the first available probed index ${index}.`,items:table.map((b,i)=>`${i}: ${b.join(" → ")||"—"}`),active:index});}result=table.map((b,i)=>`${i}: ${b.join(" → ")||"—"}`);}
   else if(c==="Rehashing"){const keys=parseNums(v);if(!keys.length)throw Error("Enter keys separated by commas.");const size=13,table=Array(size).fill(null);steps.push({label:"Create larger table",detail:"The new table has 13 slots instead of 7. All keys must be inserted again.",items:table.map((x,i)=>`${i}: —`)});keys.forEach(k=>{const idx=((k%size)+size)%size;let p=idx;while(table[p]!==null)p=(p+1)%size;table[p]=k;steps.push({label:`Reinsert ${k}`,detail:`Calculate ${k} modulo 13 and place it at index ${p}.`,items:table.map((x,i)=>`${i}: ${x??"—"}`),active:p});});result=table.map((x,i)=>`${i}: ${x??"—"}`);}
   else if(c==="Multiway Merge"){
    const runs=arrayInput.split(";").map(r=>parseNums(r));
    if(runs.length<2||runs.some(r=>!r.length)) throw Error("Enter at least two sorted runs separated by semicolons, for example 1,4;2,5;3,6.");
    if(runs.some(r=>r.some((x,i)=>i>0&&r[i-1]>x))) throw Error("Each run must already be sorted.");
    const pointers=runs.map(()=>0); result=[];
    while(runs.some((r,i)=>pointers[i]<r.length)){
      let best=-1;
      for(let i=0;i<runs.length;i++){
        if(pointers[i]<runs[i].length&&(best<0||runs[i][pointers[i]]<runs[best][pointers[best]])) best=i;
      }
      const value=runs[best][pointers[best]];
      pointers[best]++;
      result.push(value);
      steps.push({label:`Take ${value} from run ${best+1}`,detail:`Compare the front values of all runs and take the smallest available value, ${value}.`,items:[...result]});
    }
    steps.push({label:"Merge complete",detail:`Combined sorted run: ${result.join(", ")}.`,items:result});
   }
   else if(["External Sorting","Polyphase Merge"].includes(c)){const arr=parseNums(v);if(!arr.length)throw Error("Enter numbers to demonstrate external sorting.");const chunk=3,runs=[];for(let i=0;i<arr.length;i+=chunk){const run=arr.slice(i,i+chunk).sort((a,b)=>a-b);runs.push(run);steps.push({label:`Sort run ${runs.length}`,detail:`Load a small chunk into memory, sort it, and write it back: ${run.join(", ")}.`,items:run,aux:`Temporary runs: ${runs.map(r=>`[${r.join(",")}]`).join(" ")}`});}let merged=runs.flat().sort((a,b)=>a-b);steps.push({label:"Merge sorted runs",detail:`Merge the small sorted runs into one ordered output: ${merged.join(", ")}.`,items:merged});result=merged;}
   else if(c==="Expression Tree"){const r=infixConvert(v);steps=[{label:"Read expression",detail:`Start with ${v}. Convert its operator order to understand which operation belongs below another.`,items:tokenize(v)},{label:"Build expression structure",detail:`The highest-level operator becomes the root. Operands become leaves; higher-precedence operations are grouped lower in the tree.`,items:r.out},{label:"Expression tree ready",detail:`Postfix form ${r.out.join(" ")} represents the same expression.`,items:r.out}];result=r.out;}
   else if(["Binary Tree","Binary Search Tree","AVL Tree","B-tree"].includes(c)){
    const treeValues=[...items];
    if(op==="Insert"){
     const nums=parseNums(v);if(!nums.length)throw Error("Enter one or more numbers separated by commas to insert.");
     result=[...treeValues];
     nums.forEach(n=>{if((c!=="Binary Tree")&&result.includes(n)){steps.push({label:`Skip duplicate ${n}`,detail:"This search-tree example stores each key only once.",items:[...result]});return;}result.push(n);steps.push({label:`Insert ${n}`,detail:c==="Binary Tree"?`Place ${n} in the next open position, filling the tree level by level.`:`Start at the root. Compare ${n} with each node: smaller goes left and larger goes right until an empty child position is found.`,items:[...result],active:result.length-1});});
    } else if(op==="Search"){
     if(v==="")throw Error("Enter the value you want to search for.");const wanted=Number(v);if(!Number.isFinite(wanted))throw Error("Enter a numeric value to search for.");result=treeValues;
     if(c==="Binary Tree"||c==="B-tree") {const at=treeValues.indexOf(wanted);treeValues.forEach((n,i)=>steps.push({label:`Check node ${n}`,detail:`Compare ${n} with ${wanted}. ${n===wanted?"The value matches.":"Not a match, continue to the next stored node."}`,items:treeValues,active:i}));if(at<0)steps.push({label:"Not found",detail:`${wanted} is not in this tree.`,items:treeValues});}
     else {let root=null;treeValues.forEach((value,orderIndex)=>{if(!root){root={value,orderIndex,left:null,right:null};return;}let node=root;while(true){const side=value<node.value?"left":"right";if(!node[side]){node[side]={value,orderIndex,left:null,right:null};break;}node=node[side];}});let node=root,found=false;while(node){const n=node.value;found=n===wanted;steps.push({label:`Compare with ${n}`,detail:`Compare ${wanted} with ${n}. ${found?"The key is found.":wanted<n?"The target is smaller, so follow the left child.":"The target is larger, so follow the right child."}`,items:treeValues,active:node.orderIndex});if(found)break;node=wanted<n?node.left:node.right;}if(!found)steps.push({label:"Search complete",detail:`${wanted} was not found. The search stops when the required child link is empty.`,items:treeValues});}
    } else if(op==="Delete"){
     if(v==="")throw Error("Enter the value you want to delete.");const wanted=Number(v);const at=treeValues.indexOf(wanted);if(at<0)throw Error(`${wanted} is not in the tree, so nothing can be deleted.`);
     if(c==="Binary Tree"){result=[...treeValues];const replacement=result.at(-1);steps.push({label:`Find node ${wanted}`,detail:`Locate ${wanted} in the level-order tree.`,items:result,active:at});result[at]=replacement;result.pop();steps.push({label:`Replace with ${replacement}`,detail:`Copy the deepest, rightmost node value ${replacement} into the deleted node's position, then remove the old last node.`,items:result,active:at});}
     else {result=treeValues.filter(x=>x!==wanted);steps.push({label:`Locate ${wanted}`,detail:`Follow the search-tree comparisons until ${wanted} is reached.`,items:treeValues,active:at});steps.push({label:`Delete ${wanted}`,detail:"Remove the key and reconnect its child subtree. This teaching view rebuilds the remaining keys to show the resulting search tree.",items:result});}
    } else throw Error("Choose Insert, Delete, or Search.");
   }
   else if(c==="Open Addressing"){const keys=parseNums(v);if(!keys.length)throw Error("Enter numeric keys separated by commas.");const table=Array(7).fill(null);result=table;keys.forEach(k=>{let i=((k%7)+7)%7,tries=0;while(table[i]!==null&&tries<7){steps.push({label:`Collision at ${i}`,detail:`Index ${i} is occupied. Open addressing checks another slot in the same table.`,items:table.map(x=>x??"—"),active:i});i=(i+1)%7;tries++;}if(tries===7)throw Error("Table is full.");table[i]=k;steps.push({label:`Place ${k}`,detail:`Store ${k} at empty index ${i}.`,items:table.map(x=>x??"—"),active:i});});}
   else throw Error("This concept is currently in explanation mode. Try one of the supported interactive operations.");
   if(!steps.length)throw Error("No operation steps were created. Check your input.");showSteps(steps,`${c} executed successfully. Follow the steps to understand the changes.`,result);
  }catch(e){setNotice(`Let's fix that: ${e.message}`);if(voiceOn&&"speechSynthesis"in window){window.speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(`Let's fix that. ${e.message}`);window.speechSynthesis.speak(u);}}
 }
 function reset(){setItems([]);if(activeConcept==="Graph Traversals")setGraphData({vertices:[],edges:[]});setFrames([]);setFrameIndex(0);setInput("");setArrayInput("");setTarget("");setNotice("Simulator cleared. Enter a new value to begin.");if("speechSynthesis"in window)window.speechSynthesis.cancel();}
 function explainTutor(q){const lower=q.toLowerCase();const found=concepts.find(c=>lower.includes(c.id.toLowerCase()));if(found)return `${found.id}: ${found.description} ${found.how}`;if(lower.includes("mistake")||lower.includes("error"))return "No problem. Read the message under the simulator, check the input format, and try a smaller example. An error is a clue about what needs correcting.";if(lower.includes("complexity"))return "Time complexity describes how the number of steps grows as input gets bigger. For example, linear search can inspect n values (O(n)); binary search halves the range each time (O(log n)).";return `Let's break it down simply. ${concept.description} ${concept.how}`;}
 function sendChat(e){e?.preventDefault();const q=chatInput.trim();if(!q)return;setMessages(m=>[...m,{from:"user",text:q},{from:"bot",text:explainTutor(q)}]);setChatInput("");}
 const progress=Math.round(completed.length/concepts.length*100),score=quiz.filter((q,i)=>answers[i]===q.answer).length;
 const nav=[["Home",Home],["Learning",BookOpen],["Practice",Code2],["Assessment",ClipboardCheck],["AI Tutor",Sparkles],["Profile",UserRound],["Settings",Settings]];
 const groups=[["Foundations",["Stack","Queue","Linked List"]],["Trees & Expressions",["Binary Tree","Binary Search Tree","AVL Tree","Expression Tree","Infix to Postfix","Postfix Expression Evaluation","Tower of Hanoi","B-tree"]],["Graphs",["Graph Traversals"]],["Hashing",concepts.filter(c=>c.id.startsWith("Hashing")||c.id==="Open Addressing"||c.id==="Rehashing").map(c=>c.id)],["Searching",["Linear Search","Binary Search"]],["Sorting",["Internal Sorting","Bubble Sort","Shell Sort","External Sorting","Multiway Merge","Polyphase Merge"]]];
 const inputKind=["Linear Search","Binary Search","Bubble Sort","Shell Sort","Internal Sorting","External Sorting","Polyphase Merge"].includes(activeConcept)?"array":activeConcept==="Multiway Merge"?"runs":activeConcept.startsWith("Hashing")||["Open Addressing","Rehashing"].includes(activeConcept)?"keys":"single";
 const actions=activeConcept==="Stack"?["Push","Pop","Peek"]:activeConcept==="Queue"?["Enqueue","Dequeue","Peek"]:activeConcept==="Linked List"?["Insert","Delete","Search"]:activeConcept==="Graph Traversals"?["Add Vertex","Add Edge","Delete Vertex","Delete Edge","Search","BFS","DFS"]:activeConcept==="Binary Search Tree"||activeConcept==="AVL Tree"||activeConcept==="Binary Tree"||activeConcept==="B-tree"?["Insert","Delete","Search"]:activeConcept==="Tower of Hanoi"?["Solve"]:["Execute"];
 return <div className="app-shell">
  <aside className={`sidebar ${sidebarOpen?"sidebar-open":""}`}><div className="brand" onClick={()=>setPage("Home")}><div className="brand-mark"><span>DS</span><b>Play</b><Sparkles size={12}/></div><div><strong>DS Play</strong><small>Visual learning platform</small></div><button className="mobile-close" onClick={()=>setSidebarOpen(false)}><X size={17}/></button></div><div className="side-label">WORKSPACE</div><nav>{nav.map(([n,I])=><button key={n} className={`nav-link ${page===n||(page==="Simulator"&&n==="Learning")?"active":""}`} onClick={()=>{setPage(n);setSidebarOpen(false)}}><I size={17}/><span>{n}</span></button>)}</nav><div className="sidebar-bottom"><div className="streak-card"><div className="streak-icon"><Flame size={17}/></div><div><b>Keep learning!</b><small>{completed.length} topics explored</small></div></div><div className="mini-profile"><div className="avatar">{profileName[0]?.toUpperCase()}</div><div><b>{profileName}</b><small>DS Play learner</small></div><Settings size={15} onClick={()=>setPage("Settings")}/></div></div></aside>
  {sidebarOpen&&<div className="scrim" onClick={()=>setSidebarOpen(false)}/>}
  <main className="main"><header className="topbar"><button className="menu-btn" onClick={()=>setSidebarOpen(true)}><Menu size={19}/></button><div className="breadcrumb"><span>DS Play</span><ChevronRight size={14}/><b>{page==="Simulator"?activeConcept:page}</b></div><div className="top-actions"><label className="search-box"><Search size={15}/><input placeholder="Search concepts..." onKeyDown={e=>{if(e.key==="Enter"){const c=concepts.find(c=>c.id.toLowerCase().includes(e.currentTarget.value.toLowerCase()));if(c)chooseConcept(c.id);}}}/><kbd>↵</kbd></label><button className="avatar top-avatar" onClick={()=>setPage("Profile")}>{profileName[0]?.toUpperCase()}</button></div></header>
  <div className="content">
   {page==="Home"&&<div className="page-stack"><section className="hero-card"><div className="hero-copy"><span className="eyebrow">WELCOME TO YOUR PLAYGROUND</span><h1>Learn Data Structures.<br/><em>One step at a time.</em></h1><p>Understand concepts, watch algorithms work, and build confidence through interactive practice.</p><button className="primary-btn" onClick={()=>setPage("Learning")}>Start learning <ChevronRight size={15}/></button></div><div className="hero-art"><div className="art-window"><div className="art-stack"><b>01</b><b>10</b><b>11</b></div><div className="art-code"><span>if (learn)</span><span>visualise();</span><span>practice();</span></div></div></div></section><div className="stats-grid"><div className="stat-card"><div className="stat-icon purple"><BookOpen size={18}/></div><div><small>Topics available</small><strong>{concepts.length}</strong></div></div><div className="stat-card"><div className="stat-icon orange"><Trophy size={18}/></div><div><small>Topics explored</small><strong>{completed.length}</strong></div></div><div className="stat-card"><div className="stat-icon green"><Flame size={18}/></div><div><small>Your progress</small><strong>{progress}%</strong></div></div></div><div className="section-heading"><div><span className="eyebrow">PICK UP WHERE YOU LEFT</span><h2>Explore a concept</h2><p>Start with a beginner explanation, then try the visual simulator.</p></div><button className="text-btn" onClick={()=>setPage("Learning")}>View all <ChevronRight size={14}/></button></div><div className="concept-grid">{concepts.slice(0,6).map(c=><ConceptCard key={c.id} concept={c} onClick={()=>chooseConcept(c.id)}/>)}</div></div>}
   {page==="Learning"&&<div className="page-stack"><PageTitle eyebrow="LEARNING LIBRARY" title="Explore Data Structures & Algorithms" subtitle="Every topic starts with the basics. Choose any topic to learn before you simulate."/><div className="learning-banner"><BookOpen size={25}/><div><b>New to a concept? Start here.</b><p>Each lesson explains what it is, why it is used, and what to do in the simulator.</p></div></div>{groups.map(([g,ids])=><section className="topic-group" key={g}><h2>{g}</h2><div className="concept-grid large">{ids.map(id=>concepts.find(c=>c.id===id)).filter(Boolean).map(c=><ConceptCard key={c.id} concept={c} onClick={()=>chooseConcept(c.id)}/>)}</div></section>)}</div>}
   {page==="Simulator"&&<div className="page-stack"><div className="sim-title"><button className="back-button" onClick={()=>setPage("Learning")}><ChevronRight size={17}/></button><div><span className="eyebrow">LEARN · VISUALISE · TRY</span><h1>{activeConcept} <span className="title-pill">Interactive lesson</span></h1><p>{concept.subtitle}</p></div><div className="sim-heading-actions"><button className={`outline-btn voice-toggle ${voiceOn?"voice-enabled":""}`} onClick={()=>{setVoiceOn(x=>!x);if(voiceOn&&"speechSynthesis"in window)window.speechSynthesis.cancel();}}>{voiceOn?<Volume2 size={15}/>:<VolumeX size={15}/>} Voice {voiceOn?"ON":"OFF"}</button><button className="outline-btn reset-btn" onClick={reset}><RotateCcw size={15}/> Reset</button></div></div>
    <section className="panel beginner-panel"><div className="panel-heading"><div><span className="panel-kicker">FIRST, UNDERSTAND THE IDEA</span><h3>What is {activeConcept}?</h3></div><span className="difficulty easy">Beginner friendly</span></div><p>{concept.description}</p><div className="beginner-how"><Sparkles size={17}/><span><b>What you will do:</b> {concept.how}</span></div></section>
    <div className="sim-layout"><section className="panel visual-panel"><div className="panel-heading"><div><span className="panel-kicker">LIVE CANVAS</span><h3>Watch what happens</h3></div><span className="live-badge"><i/> Ready</span></div>
      <div className={`visual-stage ${activeConcept==="Queue"?"queue-stage":""} ${activeConcept==="Linked List"?"list-stage":""}`}>{["Binary Tree","Binary Search Tree","AVL Tree"].includes(activeConcept)?<TreeVisual values={current?.items||[]} concept={activeConcept}/>:activeConcept==="Graph Traversals"?<GraphVisual vertices={graphData.vertices} edges={graphData.edges} visited={current?.items||[]}/>:<div className="items-visual">{current?.items?.length?current.items.map((x,i)=><React.Fragment key={`${x}-${i}`}><div className={`data-item ${current.active===i?"highlight":""}`}>{String(x)}</div>{activeConcept==="Linked List"&&i<current.items.length-1&&<span className="node-link">→</span>}</React.Fragment>):<div className="empty-state"><Layers3 size={30}/><b>Waiting for your first step</b><span>The canvas is empty. Enter data below and execute.</span></div>}</div>}<div className="stage-floor">{activeConcept==="Stack"?"TOP ↑":activeConcept==="Queue"?"FRONT → REAR":activeConcept==="Linked List"?"HEAD → NEXT":"INPUT → VISUAL RESULT"}</div></div>
      {current?.aux&&<div className="notice"><span className="notice-dot"/>{current.aux}</div>}<div className={`notice ${notice.startsWith("Let's fix")?"warning":""}`}><span className="notice-dot"/>{notice}</div>
      <div className="control-label">YOUR INPUT</div>
      {inputKind==="array"||inputKind==="runs"?<><label className="value-entry"><span>{inputKind==="runs"?"Sorted runs (separate with ;)":"Values (comma separated)"}</span><input value={arrayInput} onChange={e=>setArrayInput(e.target.value)} placeholder={inputKind==="runs"?"1,4;2,5;3,6":"8, 3, 6, 1, 5"}/></label>{["Linear Search","Binary Search"].includes(activeConcept)&&<label className="value-entry"><span>Target value</span><input value={target} onChange={e=>setTarget(e.target.value)} placeholder="Enter target"/></label>}</>:<label className="value-entry"><span>{activeConcept==="Tower of Hanoi"?"Number of disks":activeConcept==="Graph Traversals"?"Graph operation / start vertex (A or A-B)":"Enter value / expression / keys"}</span><input value={input} onChange={e=>setInput(e.target.value)} placeholder={activeConcept==="Graph Traversals"?(operation.includes("Edge")?"A-B":"A"):activeConcept==="Infix to Postfix"||activeConcept==="Expression Tree"?"A+B*C":activeConcept==="Postfix Expression Evaluation"?"5 2 3 * +":activeConcept==="Tower of Hanoi"?"3":activeConcept.includes("Hashing")?"10, 17, 24, 31":"Enter data to begin"}/></label>}
      <div className="operation-buttons">{actions.map(a=><button className="op-btn" key={a} onClick={()=>{setOperation(a);execute(a);}}>{a}</button>)}{activeConcept==="Open Addressing"&&<button className="op-btn" onClick={execute}>Linear probe demo</button>}</div>
      <button className="primary-btn execute-btn" onClick={execute}><Play size={14} fill="currentColor"/> Execute simulation</button>
    </section>
    <section className="panel steps-panel"><div className="panel-heading"><div><span className="panel-kicker">YOUR TUTOR EXPLAINS</span><h3>Step-by-step breakdown</h3></div><span className="step-count">{frames.length?`${frameIndex+1}/${frames.length}`:"0 steps"}</span></div>{frames.length?<><div className="step-track">{frames.map((f,i)=><button key={i} className={`step-row ${i===frameIndex?"current":""} ${i<frameIndex?"done":""}`} onClick={()=>setFrameIndex(i)}><span className="step-number">{i<frameIndex?<CheckCircle2 size={15}/>:String(i+1).padStart(2,"0")}</span><span><b>{f.label}</b><small>{f.detail}</small></span><ChevronRight size={15}/></button>)}</div><div className="step-nav"><button className="outline-btn" disabled={frameIndex===0} onClick={()=>setFrameIndex(i=>i-1)}>Previous</button><button className="primary-btn" disabled={frameIndex===frames.length-1} onClick={()=>setFrameIndex(i=>i+1)}>Next step <ChevronRight size={14}/></button></div></>:<div className="no-steps"><div className="no-steps-icon"><Play size={19}/></div><b>Your tutor is ready</b><p>Execute an operation. Each step will appear here with a simple explanation.</p></div>}<div className="tip-card"><Sparkles size={17}/><div><b>Learning tip</b><p>Try predicting what happens before pressing Execute. Turn Voice ON to hear every step continuously; the visualizer advances when the explanation finishes.</p></div></div></section>
    <section className="panel code-panel"><div className="panel-heading"><div><span className="panel-kicker">SOURCE CODE</span><h3>{activeConcept} · Code example</h3><p className="code-subtitle">A short beginner-friendly program. Pick a language below.</p></div><Code2 size={20}/></div><div className="language-tabs">{["C","C++","Python","Java"].map(lang=><button key={lang} className={codeLanguage===lang?"active":""} onClick={()=>{setCodeLanguage(lang);setCopied(false);}}>{lang}</button>)}</div>{(()=>{const ex=getCodeExample(activeConcept,codeLanguage);return <><div className="code-topic-note">{ex.note}</div><div className="code-file-bar"><span>{ex.file}</span><button className="copy-btn" onClick={()=>{try{navigator.clipboard.writeText(ex.code);setCopied(true);setTimeout(()=>setCopied(false),1500);}catch(e){}}}>{copied?"Copied!":"Copy code"}</button></div><pre className="code-block"><code>{ex.code}</code></pre></>;})()}<div className="code-explain"><Sparkles size={15}/><div><b>How to use this code</b><p>Copy the code into a file with the name shown above and run it. Change the numbers in the code and run it again to see how the output changes.</p></div></div></section></div>
   </div>}
   {page==="Practice"&&<div className="page-stack"><PageTitle eyebrow="YOUR LEARNING QUEST" title="Practice adventure" subtitle="Follow the path. Complete a topic to unlock the next checkpoint."/><div className="practice-callout"><Trophy size={22}/><div><b>Every step makes you stronger</b><p>Run the simulator for a topic to mark it complete. The next checkpoint then unlocks automatically.</p></div></div><div className="practice-progress"><b>{completed.length} of {concepts.length} topics explored</b><div className="progress-track"><span style={{width:`${progress}%`}}/></div></div><div className="practice-map">{concepts.map((c,i)=>{const unlocked=i===0||completed.includes(concepts[i-1].id),done=completed.includes(c.id);return <div className={`map-stop ${done?"map-done":""} ${unlocked?"":"map-locked"}`} key={c.id}><div className="map-connector">{done?<CheckCircle2 size={17}/>:unlocked?i+1:<Lock size={14}/>}</div><div className="exercise-card"><div className="exercise-copy"><b>{c.id}</b><p>{c.subtitle}</p><span className={`difficulty ${done?"easy":i%3===0?"easy":i%3===1?"medium":"hard"}`}>{done?"Completed":unlocked?"Unlocked":"Locked"}</span></div>{done?<span className="map-status">✓ Completed</span>:unlocked?<button className="primary-btn" onClick={()=>chooseConcept(c.id)}>Start <ChevronRight size={14}/></button>:<span className="map-status"><Lock size={13}/> Locked</span>}</div></div>})}</div></div>}
   {page==="Assessment"&&<div className="page-stack"><PageTitle eyebrow="CHECK YOUR UNDERSTANDING" title="Quick assessment" subtitle="Test the fundamentals. Review the explanation after submitting."/><div className="assessment-summary"><ClipboardCheck size={24}/><div><b>DS Play basics</b><p>{quiz.length} questions · One correct answer per question</p></div><span>{Object.keys(answers).length}/{quiz.length} answered</span></div>{submitted&&<div className="score-banner"><Trophy size={24}/><div><b>You scored {score} out of {quiz.length}</b><p>{score>=6?"Excellent work. Keep exploring!":"Good effort. Read the explanations and try again."}</p></div><strong>{Math.round(score/quiz.length*100)}%</strong></div>}<div className="quiz-list">{quiz.map((q,i)=><div className="quiz-question" key={q.q}><div className="question-top"><span>QUESTION {i+1}</span></div><h3>{q.q}</h3><div className="answer-options">{q.options.map((o,j)=><label className={`answer-option ${answers[i]===j?"chosen":""} ${submitted&&j===q.answer?"correct":""} ${submitted&&answers[i]===j&&j!==q.answer?"incorrect":""}`} key={o}><input type="radio" name={`q${i}`} checked={answers[i]===j} disabled={submitted} onChange={()=>setAnswers(a=>({...a,[i]:j}))}/>{o}</label>)}</div>{submitted&&<p className="answer-explanation">{q.why}</p>}</div>)}</div><div className="quiz-actions"><button className="primary-btn" onClick={()=>{if(submitted){setAnswers({});setSubmitted(false);}else setSubmitted(true);}}>{submitted?"Try again":"Submit assessment"}</button></div></div>}
   {page==="AI Tutor"&&<div className="page-stack"><PageTitle eyebrow="YOUR LEARNING COMPANION" title="Ask the DS Play tutor" subtitle="Ask for a beginner explanation, a hint, or help understanding a mistake."/><section className="panel chat-panel"><div className="chat-header"><div className="tutor-avatar"><Sparkles size={19}/></div><div><b>DS Play Tutor</b><span><i/> Beginner-friendly learning helper</span></div></div><div className="chat-messages">{messages.map((m,i)=><div className={`message ${m.from}`} key={i}><div className="message-avatar"><Sparkles size={14}/></div><div className="message-bubble">{m.text}</div></div>)}</div><form className="chat-form" onSubmit={sendChat}><input value={chatInput} onChange={e=>setChatInput(e.target.value)} placeholder="Ask: why do we use a stack?"/><button className="primary-btn"><Send size={16}/></button></form><p className="demo-note">Tutor responses are built-in educational guidance. A live generative AI service is not connected.</p></section></div>}
   {page==="Profile"&&<div className="page-stack"><PageTitle eyebrow="YOUR SPACE" title="Student profile" subtitle="Track your learning progress."/><div className="profile-hero"><div className="profile-avatar">{profileName[0]?.toUpperCase()}</div><div><h2>{profileName}</h2><p>DS Play learner</p></div><div className="profile-hero-stat"><strong>{progress}%</strong><span>Progress</span></div></div><div className="stats-grid"><div className="stat-card"><small>Topics explored</small><strong>{completed.length}</strong></div><div className="stat-card"><small>Topics available</small><strong>{concepts.length}</strong></div></div></div>}
   {page==="Settings"&&<div className="page-stack"><PageTitle eyebrow="PREFERENCES" title="Settings" subtitle="Personalise your learning experience."/><div className="panel settings-panel"><label className="form-label">Display name<input value={profileName} onChange={e=>setProfileName(e.target.value)}/></label><button className="primary-btn" onClick={()=>localStorage.setItem("dsplay-name",JSON.stringify(profileName))}>Save name</button><div className="settings-divider"/><div className="settings-heading"><div className="settings-icon mint">{voiceOn?<Volume2/>:<VolumeX/>}</div><div><h3>Voice assistant</h3><p>Explain each simulation step aloud and automatically continue until the process is complete.</p></div></div><button className="outline-btn" onClick={()=>{setVoiceOn(v=>!v);if(voiceOn&&"speechSynthesis"in window)window.speechSynthesis.cancel();}}>{voiceOn?"Turn voice off":"Turn voice on"}</button><label className="form-label">Speaking speed<input type="range" min="0.7" max="1.2" step="0.05" value={voiceRate} onChange={e=>setVoiceRate(Number(e.target.value))}/></label><div className="settings-info"><b>About this prototype</b><span>Progress and preferences are stored in this browser. Voice uses your browser's built-in speech synthesis.</span></div></div></div>}
  </div><footer className="footer"><span>© 2026 DS Play</span><span>Learn · Practise · Visualise · Grow</span></footer></main></div>;
}
function PageTitle({eyebrow,title,subtitle}){return <div className="page-title-row"><div><span className="eyebrow">{eyebrow}</span><h1>{title}</h1><p>{subtitle}</p></div></div>}
function ConceptCard({concept,onClick}){const Icon=concept.icon;return <button className="concept-card" onClick={onClick}><div className={`concept-icon ${concept.color}`}><Icon size={22}/></div><div className="concept-card-copy"><b>{concept.id}</b><p>{concept.subtitle}</p></div><ChevronRight size={16}/></button>}

function TreeVisual({values,concept}){
 const nodes=[];
 if(concept==="Binary Tree"){values.forEach((v,i)=>nodes.push({v,x:50/(2**Math.floor(Math.log2(i+1)))+(Math.floor((i+1)-2**Math.floor(Math.log2(i+1)))+0.5)*(100/(2**Math.floor(Math.log2(i+1)))),y:12+Math.floor(Math.log2(i+1))*37,parent:i?values[Math.floor((i-1)/2)]:-1}));}
 else {const root={v:null,left:null,right:null,x:50,y:12,parent:-1};values.forEach(v=>{if(root.v===null){root.v=v;return;}let n=root,depth=0;while(true){depth++;if(v<n.v){if(!n.left){n.left={v,left:null,right:null,x:50-42/(depth),y:12+depth*35,parent:0};break;}n=n.left;}else{if(!n.right){n.right={v,left:null,right:null,x:50+42/(depth),y:12+depth*35,parent:0};break;}n=n.right;}}});function flatten(n,x1,x2,depth,parent){if(!n)return; n.x=(x1+x2)/2;n.y=12+depth*35;nodes.push({...n,parent});flatten(n.left,x1,n.x,depth+1,n.v);flatten(n.right,n.x,x2,depth+1,n.v);}nodes.length=0;if(root.v!==null)flatten(root,5,95,0,null);}
 return <div className="tree-canvas"><svg viewBox="0 0 100 100" preserveAspectRatio="none">{nodes.filter(n=>n.parent!==-1&&n.parent!==null).map((n,i)=>{const p=nodes.find(x=>x.v===n.parent);return p?<line key={i} x1={p.x} y1={p.y} x2={n.x} y2={n.y} stroke="#c9c6f8" strokeWidth="1.2"/>:null;})}</svg>{nodes.map((n,i)=><div key={`${n.v}-${i}`} className="tree-node" style={{left:`${n.x}%`,top:`${n.y}%`}}>{n.v}</div>)}</div>;
}

function GraphVisual({vertices,edges,visited}){
 if(!vertices.length)return <div className="empty-state"><Network size={30}/><b>Your graph is empty</b><span>Add vertices, then connect them with edges such as A-B.</span></div>;
 const points=vertices.map((v,i)=>({v,x:50+37*Math.cos((2*Math.PI*i/Math.max(vertices.length,1))-Math.PI/2),y:50+35*Math.sin((2*Math.PI*i/Math.max(vertices.length,1))-Math.PI/2)}));
 return <div className="graph-canvas"><svg viewBox="0 0 100 100" preserveAspectRatio="none">{edges.map(([a,b],i)=>{const p=points.find(x=>x.v===a),q=points.find(x=>x.v===b);return p&&q?<line key={i} x1={p.x} y1={p.y} x2={q.x} y2={q.y} stroke="#b9c6e8" strokeWidth="1.5"/>:null;})}</svg>{points.map(p=><div key={p.v} className={`graph-node ${visited.includes(p.v)?"graph-visited":""}`} style={{left:`${p.x}%`,top:`${p.y}%`}}>{p.v}</div>)}</div>;
}
